package app;

import app.repositories.AuditLogRepository;
import app.repositories.CategoryRepository;
import app.repositories.CustomerRepository;
import app.repositories.OrderLineRepository;
import app.repositories.OrderRepository;
import app.repositories.ProductRepository;
import app.repositories.ProductTagRepository;
import app.repositories.TagRepository;
import java.util.function.Function;

/** What services depend on: a repository per table and a transaction. Each service operation runs in transaction(): committed when it ends, rolled back when it fails. */
public interface UnitOfWork {
    CustomerRepository customers();
    CategoryRepository categories();
    ProductRepository products();
    OrderRepository orders();
    OrderLineRepository orderLines();
    TagRepository tags();
    ProductTagRepository productTags();
    AuditLogRepository auditLog();

    /** Runs work with the repositories of the transaction; commits when it ends, rolls back when it throws. */
    <T> T transaction(Function<UnitOfWork, T> work);
}

