package app.entities;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.IdClass;
import jakarta.persistence.Table;
import java.io.Serializable;
import java.time.OffsetDateTime;
import org.hibernate.annotations.DynamicInsert;

/** A row of the "audit_log" table. */
// The table has no primary key: rows are told apart by all their columns, for reading only, and the
// tests create that key in their own database
@Entity
@Table(name = "audit_log")
@DynamicInsert
@IdClass(AuditLog.Key.class)
public class AuditLog {
    /** The key of a row: at, message. */
    public record Key(OffsetDateTime at, String message) implements Serializable {}

    @Id
    @Column(name = "at", nullable = false)
    private OffsetDateTime at;

    @Id
    @Column(name = "message", nullable = false, columnDefinition = "text")
    private String message;

    public OffsetDateTime getAt() {
        return at;
    }

    public void setAt(OffsetDateTime at) {
        this.at = at;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }
}

