/** A row of the "products" table. */
@Entity
@Table(name = "products", indexes = { @Index(name = "ix_products_status", columnList = "status"), @Index(columnList = "category_id") })
@DynamicInsert
@Check(constraints = "price >= 0")
public class Product {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id", nullable = false)
    @JdbcTypeCode(SqlTypes.INTEGER)
    private Long id;

    @Column(name = "category_id", nullable = false)
    private Long categoryId;

    @Column(name = "name", nullable = false, length = 100)
    private String name;

    @Column(name = "price", nullable = false, precision = 10, scale = 2)
    private BigDecimal price;

    @Column(name = "status", nullable = false, length = 10)
    private String status;

    @Column(name = "version", nullable = false)
    @ColumnDefault("1")
    private Integer version;

    @Column(name = "deleted_at")
    private OffsetDateTime deletedAt;

    /** The Category this row points to (category_id); read only: the key columns are written. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "category_id", referencedColumnName = "id", insertable = false, updatable = false, foreignKey = @ForeignKey(name = "fk_products_category"))
    private Category category;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getCategoryId() {
        return categoryId;
    }

    public void setCategoryId(Long categoryId) {
        this.categoryId = categoryId;
    }

