        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<Tag> visible() {
        return rows.values().stream().filter((row) -> true).sorted(Comparator.comparing(MemoryTagRepository::keyOf, MemoryTagRepository::compareKeys));
    }

    @Override
    public Optional<Tag> findById(Long id) {
        return visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
    }

    @Override
    public Page<Tag> list(int offset, int limit) {
        List<Tag> rows = visible().toList();
        return new Page<>(rows.stream().skip(offset).limit(limit).toList(), rows.size(), offset, limit);
    }

    @Override
    public Tag insert(Tag entity) {
        if (entity.getId() == null) entity.setId(nextId++);
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public Tag update(Tag entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public void delete(Tag entity) {
        rows.remove(keyOf(entity));
    }
}

