package app.repositories;

import app.common.Page;
import app.entities.Tag;
import java.util.Optional;

/** Where tags rows are kept. Services depend only on this interface. */
public interface TagRepository {
    /** The row with this primary key, if there is one. */
    Optional<Tag> findById(Long id);

    /** At most limit rows from offset, by primary key, and how many there are. */
    Page<Tag> list(int offset, int limit);

    /** Stores a new row; the values the database fills are read back. */
    Tag insert(Tag entity);

    /** Stores the changes made to a row read from this repository. */
    Tag update(Tag entity);

    /** Removes a row read from this repository. */
    void delete(Tag entity);
}

