package app;

import app.entities.Category;
import app.entities.Customer;
import app.entities.Order;
import app.entities.OrderLine;
import app.entities.Product;
import app.entities.ProductTag;
import app.entities.Tag;
import java.math.BigDecimal;

/** Rows for the tests: valid values for every column, and the rows they point to. */
final class Factories {
    private Factories() {}

    /** A valid Customer that is not stored yet; n makes its unique values differ. */
    static Customer newCustomer(int n) {
        Customer entity = new Customer();
        entity.setEmail("email-" + n);
        entity.setPasswordHash("passwordhash-" + n);
        return entity;
    }

    /** A stored Customer. */
    static Customer addCustomer(UnitOfWork uow, int n) {
        Customer entity = newCustomer(n);
        return uow.customers().insert(entity);
    }

    /** A valid Category that is not stored yet; n makes its unique values differ. */
    static Category newCategory(int n) {
        Category entity = new Category();
        entity.setName("name-" + n);
        return entity;
    }

    /** A stored Category. */
    static Category addCategory(UnitOfWork uow, int n) {
        Category entity = newCategory(n);
        return uow.categories().insert(entity);
    }

    /** A valid Product that is not stored yet; n makes its unique values differ. */
    static Product newProduct(int n) {
        Product entity = new Product();
        entity.setName("name-" + n);
        entity.setPrice(new BigDecimal((n % 10000) + ".50"));
        entity.setStatus("status-" + n);
        entity.setVersion((n));
        return entity;
    }

    /** A stored Product, with the rows it points to. */
    static Product addProduct(UnitOfWork uow, int n) {
        Category parent0 = addCategory(uow, n);
        Product entity = newProduct(n);
        entity.setCategoryId(parent0.getId());
        return uow.products().insert(entity);
    }

    /** A valid Order that is not stored yet; n makes its unique values differ. */
    static Order newOrder(int n) {
        Order entity = new Order();
        return entity;
    }

    /** A stored Order, with the rows it points to. */
    static Order addOrder(UnitOfWork uow, int n) {
        Customer parent0 = addCustomer(uow, n);
        Order entity = newOrder(n);
        entity.setCustomerId(parent0.getId());
        return uow.orders().insert(entity);
    }

    /** A valid OrderLine that is not stored yet; n makes its unique values differ. */
    static OrderLine newOrderLine(int n) {
        OrderLine entity = new OrderLine();
        entity.setLine((n));
        entity.setQuantity((n));
        return entity;
    }

    /** A stored OrderLine, with the rows it points to. */
    static OrderLine addOrderLine(UnitOfWork uow, int n) {
        Order parent0 = addOrder(uow, n);
        Product parent1 = addProduct(uow, n);
        OrderLine entity = newOrderLine(n);
        entity.setOrderId(parent0.getId());
        entity.setProductId(parent1.getId());
        return uow.orderLines().insert(entity);
    }

    /** A valid Tag that is not stored yet; n makes its unique values differ. */
    static Tag newTag(int n) {
        Tag entity = new Tag();
        entity.setLabel("label-" + n);
        return entity;
    }

    /** A stored Tag. */
    static Tag addTag(UnitOfWork uow, int n) {
        Tag entity = newTag(n);
        return uow.tags().insert(entity);
    }

    /** A valid ProductTag that is not stored yet; n makes its unique values differ. */
    static ProductTag newProductTag(int n) {
        ProductTag entity = new ProductTag();
        return entity;
    }

    /** A stored ProductTag, with the rows it points to. */
    static ProductTag addProductTag(UnitOfWork uow, int n) {
        Product parent0 = addProduct(uow, n);
        Tag parent1 = addTag(uow, n);
        ProductTag entity = newProductTag(n);
        entity.setProductId(parent0.getId());
        entity.setTagId(parent1.getId());
        return uow.productTags().insert(entity);
    }
}

